def pagination(skip: int = 0, limit: int = 10):
    return {"skip": skip, "limit": limit}

@app.get("/items/")
async def list_items(pagination_params: dict = Depends(pagination)):
    # In a real app, you'd use skip/limit to query DB
    return pagination_params

from fastapi import FastAPI, Depends, Header, HTTPException

app = FastAPI()

# Sub-dependency
def get_token(authorization: str = Header(...)):
    return authorization.split(" ")[1]  # Extract token from "Bearer <token>"

# Main dependency that uses the sub-dependency
def get_current_user(token: str = Depends(get_token)):
    if token != "secret-token":
        raise HTTPException(status_code=401, detail="Invalid token")
    return {"username": "alice"}

@app.get("/users/me")
async def read_current_user(current_user: dict = Depends(get_current_user)):
    return current_user
